cypress_script:
describe('Todo List CRUD Operations', () => {
  it('should add a todo item', () => {
    cy.visit('https://todomvc.com/examples/react/dist/');
    cy.get('[aria-label="New Todo Input"]').type('Test Todo{enter}');
    cy.get('[data-testid="todo-list"] li').should('have.length', 1);
  });

  it('should not add an empty todo item', () => {
    cy.visit('https://todomvc.com/examples/react/dist/');
    cy.get('[aria-label="New Todo Input"]').type('{enter}');
    cy.get('[data-testid="todo-list"] li').should('have.length', 0);
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Todo List CRUD Operations', () => {
  test('should add a todo item', async ({ page }) => {
    await page.goto('https://todomvc.com/examples/react/dist/');
    await page.fill('[aria-label="New Todo Input"]', 'Test Todo');
    await page.press('[aria-label="New Todo Input"]', 'Enter');
    const todoList = await page.locator('[data-testid="todo-list"] li');
    await expect(todoList).toHaveCount(1);
  });

  test('should not add an empty todo item', async ({ page }) => {
    await page.goto('https://todomvc.com/examples/react/dist/');
    await page.press('[aria-label="New Todo Input"]', 'Enter');
    const todoList = await page.locator('[data-testid="todo-list"] li');
    await expect(todoList).toHaveCount(0);
  });
});
